from __future__ import annotations

import hashlib
import json
from pathlib import Path

W=Path(__file__).resolve().parent
OUT=Path(r"C:\Users\Weiwo\Downloads\m3_peak_weighting_audit_20260819_01")


def main():
    OUT.mkdir(parents=True,exist_ok=True)
    data=json.loads((W/"PEAK_WEIGHTING_COMPACT_RESULTS.json").read_text(encoding="utf-8"))
    html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>M3 Peak Weighting Audit</title><style>
:root{--bg:#07111d;--card:#0d1b2a;--line:#243a50;--text:#eaf1f8;--muted:#91a6ba;--green:#48d7ae;--blue:#6aa8ff;--orange:#ffc66d;--red:#ff8179}*{box-sizing:border-box}body{margin:0;background:#07111d;color:var(--text);font:14px/1.5 Segoe UI,Arial,sans-serif}.wrap{max-width:1280px;margin:auto;padding:28px 22px 70px}h1{margin:0;font-size:32px}.sub{color:var(--muted)}.verdict{margin:20px 0;padding:17px;border:1px solid #286052;background:#0a2925;border-radius:13px}.verdict b{font-size:22px;color:var(--green)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{grid-column:span 12;background:var(--card);border:1px solid var(--line);border-radius:13px;padding:16px;overflow:auto}.half{grid-column:span 6}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.kpi{border:1px solid var(--line);border-radius:9px;padding:10px}.kpi strong{display:block;font-size:20px}.frame{margin:12px 0;border:1px solid var(--line);border-radius:11px;padding:13px}.head{display:flex;justify-content:space-between;gap:8px}.tag{border:1px solid var(--line);padding:3px 8px;border-radius:99px;color:var(--muted)}.axis{height:82px;position:relative;margin:8px 14px 3px;border-bottom:1px solid #52708e;background:linear-gradient(90deg,transparent 31.25%,rgba(72,215,174,.14) 31.25%,rgba(72,215,174,.14) 50%,transparent 50%)}.truth{position:absolute;left:39.06%;height:100%;border-left:2px solid var(--green)}.truth:after{content:'truth 725';position:absolute;top:0;left:4px;color:var(--green);white-space:nowrap}.mode{position:absolute;top:27px;width:13px;height:13px;background:var(--orange);border-radius:50%;transform:translateX(-50%);box-shadow:0 0 0 var(--sz) rgba(255,198,109,.12)}.out{position:absolute;top:53px;width:7px;height:21px;border-left:3px solid var(--blue);transform:translateX(-50%)}.out.w0{border-color:var(--red)}.out.w4{border-color:var(--green)}.legend{color:var(--muted);font-size:12px}.vals{font:12px/1.7 ui-monospace,Consolas,monospace;display:flex;flex-wrap:wrap;gap:4px 14px}.vals b{color:var(--blue)}table{width:100%;border-collapse:collapse;min-width:780px}th,td{padding:7px;border-bottom:1px solid var(--line);text-align:right}th:first-child,td:first-child{text-align:left}.sel{background:#12372f}.bad{color:var(--red)}.warn{color:var(--orange)}.good{color:var(--green)}@media(max-width:850px){.half{grid-column:span 12}.kpis{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main class="wrap"><h1>M3 峰权重 bounded 离线比较</h1><p class="sub">Frozen modes only · W0–W8 truth-blind freeze · single-frame · audit-only</p><section class="verdict"><b>W4 p² expectation is clearly better — but only a small optimization</b><p>W4 消除 dominant hard switch，以固定平方概率连续加权；满足预定义 clear-better gates，但不减少单峰 catastrophic floor。本轮不实施。</p></section><div class="grid"><section class="card"><h2>CORE six-scan outcome</h2><div class="kpis" id="kpis"></div><p class="warn">>100 保持 4；>50 反而 42→44。收益集中在 span/MAD 与 >75，不是根因修复。</p></section><section class="card half"><h2>085223 bound</h2><p><b>8 single-mode / 3 multi-mode</b>。单峰中 >50=6、>75=3、>100=2，W0–W8 均无法改变。</p></section><section class="card half"><h2>Hard-switch cliff</h2><p>frame7 ratio=1.934，仅比 1.85 高 0.084，却让 W0 从 expectation 750.68 跳至 top 814.59。反例 frame2 中 hard top 反而更接近 truth。</p></section><section class="card"><h2>085223 lower — 11 independent frames</h2><p class="legend">轴域 600–920 mm；橙点=mode（阴影随概率），红=W0，绿=W4，蓝=其他 W；绿色竖线=725 truth。</p><div id="frames"></div></section><section class="card"><h2>W0–W8 CORE scorecard</h2><table><thead><tr><th>Scheme</th><th>mean MAD</th><th>mean std</th><th>mean span</th><th>>50</th><th>>75</th><th>>100</th></tr></thead><tbody id="table"></tbody></table></section><section class="card"><h2>结论边界</h2><p>W4 在三个 multi-mode focus frame 中只改善 frame7，恶化 frame2/frame10；大收益胜过两项小损失。它不能修复 8 个 single-mode frame，不能改变 085223 span 或 >100，也不能替代上游 Type-C 结论。<b class="good">值得作为 M3 的 bounded final-combination variant 讨论</b>，但 expected value = LOW。</p></section></div></main><script>
const D=__DATA__,F=D.focus_085223.frames,C=D.core_summary;const pos=x=>((x-600)/320*100).toFixed(3)+'%';
const b=C.W0,a=C.W4;kpis.innerHTML=[['MAD',`${b.mean_scan_lower_mad_mm.toFixed(2)}→${a.mean_scan_lower_mad_mm.toFixed(2)} mm`],['span',`${b.mean_scan_lower_span_mm.toFixed(2)}→${a.mean_scan_lower_span_mm.toFixed(2)} mm`],['>75',`${b.gt75_count}→${a.gt75_count}`],['>100',`${b.gt100_count}→${a.gt100_count}`],['>50',`${b.gt50_count}→${a.gt50_count}`]].map(([n,v])=>`<div class="kpi"><span class="sub">${n}</span><strong>${v}</strong></div>`).join('');
document.getElementById('frames').innerHTML=F.map((r,i)=>{let modes=r.modes.map(m=>`<i class="mode" style="left:${pos(m.center_mm)};--sz:${(m.probability*15).toFixed(1)}px" title="mode ${m.center_mm.toFixed(1)} p=${m.probability.toFixed(3)} σ=${m.spread_mm.toFixed(1)}"></i>`).join('');let outs=Object.entries(r.outputs_mm).map(([s,v])=>`<i class="out ${s.toLowerCase()}" style="left:${pos(v)}" title="${s} ${v.toFixed(1)}"></i>`).join('');let vals=Object.entries(r.outputs_mm).map(([s,v])=>`<span><b>${s}</b> ${v.toFixed(1)}</span>`).join('');let ms=r.modes.map(m=>`${m.center_mm.toFixed(1)}@${m.probability.toFixed(3)} σ${m.spread_mm.toFixed(1)}`).join(' · ');return `<article class="frame"><div class="head"><b>frame ${i}</b><span class="tag">${r.branch} · ${r.modes.length} mode</span></div><div class="axis"><i class="truth"></i>${modes}${outs}</div><div class="legend">${ms}</div><div class="vals">${vals}<span class="good"><b>truth</b> 725.0</span></div></article>`}).join('');
table.innerHTML=Object.entries(C).map(([s,x])=>`<tr class="${s==='W4'?'sel':''}"><td><b>${s}</b></td><td>${x.mean_scan_lower_mad_mm.toFixed(3)}</td><td>${x.mean_scan_lower_std_mm.toFixed(3)}</td><td>${x.mean_scan_lower_span_mm.toFixed(3)}</td><td>${x.gt50_count}</td><td>${x.gt75_count}</td><td>${x.gt100_count}</td></tr>`).join('');
</script></body></html>'''.replace("__DATA__",json.dumps(data,ensure_ascii=False,separators=(",",":")))
    (OUT/"index.html").write_text(html,encoding="utf-8")
    (OUT/"data.json").write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    files=[]
    for p in sorted(OUT.iterdir()): files.append({"name":p.name,"bytes":p.stat().st_size,"sha256":hashlib.sha256(p.read_bytes()).hexdigest()})
    manifest={"folder":str(OUT),"is_zip":False,"files":files}
    (W/"DOWNLOADS_MANIFEST.json").write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    (W/"DOWNLOADS_MANIFEST_TREE_HASH.md").write_text("# Downloads manifest / tree / hash\n\n"+"\n".join(f"- {x['name']} | {x['bytes']} bytes | sha256 {x['sha256']}" for x in files)+"\n",encoding="utf-8")
    print(json.dumps(manifest,indent=2,ensure_ascii=False))


if __name__=="__main__": main()
